using System.Runtime.InteropServices;

class EnvVarCheck
{
    // /proc/self/environ lists every exported variable on Linux,
    // letting us detect vars that exist but are empty.
    private static bool IsEnvVarSet(string name)
    {
        try
        {
            var environ = File.ReadAllText("/proc/self/environ");
            // Entries are separated by '\0'; each entry is KEY=VALUE
            return environ.Split('\0').Any(e =>
                e == name + "=" || e.StartsWith(name + "=", StringComparison.Ordinal));
        }
        catch
        {
            // Fallback: treat null as not set
            return Environment.GetEnvironmentVariable(name) != null;
        }
    }

