using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchive now defaults to UTF-8 entry names.
        // Our legacy Java consumer expects Shift-JIS, so we must explicitly
        // pass the encoding to preserve the old behavior.
        var shiftJis = CodePagesEncodingProvider.Instance.GetEncoding(932)
                       ?? Encoding.UTF8;
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);

        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

